import { Effect } from "effect"
import * as Shipment from "./Shipment.ts"
import { ManifestStore } from "./ManifestStore.ts"

export interface ManifestEntry {
  readonly trackingNumber: string
  readonly payload: string
}

export const prepareEntry = (
  shipment: Shipment.Shipment
): ManifestEntry => ({
  trackingNumber: shipment.trackingNumber,
  payload: Shipment.encode(shipment)
})

export const restoreEntry = (entry: ManifestEntry) =>
  Effect.gen(function*() {
    const shipment = yield* Shipment.decode(entry.payload)
    if (shipment.trackingNumber !== entry.trackingNumber) {
      return yield* Effect.fail(new Error("Tracking number mismatch"))
    }
    return shipment
  })

export const saveManifest = (shipments: ReadonlyArray<Shipment.Shipment>) =>
  Effect.gen(function*() {
    const store = yield* ManifestStore
    const entries = shipments.map(prepareEntry)
